# Generated by scripts/homebrew-formulas.py in tinhthanh/shipyard for v0.3.31-fork.9.
class Vetgo < Formula
  desc "Run coding agents on your own boxes: the berth CLI and laptop agent"
  homepage "https://github.com/tinhthanh/shipyard"
  version "0.3.31-fork.9"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.9/berth-darwin-arm64.tar.gz"
      sha256 "510d61b903e00781bec92073a34a364e7d198e34c080208f1de9791c3f37f5df"
    end
    on_intel do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.9/berth-darwin-amd64.tar.gz"
      sha256 "773631b164721fd8d39c4134ca5e783deacea3719f2c704bd7e10f787281dbfc"
    end

    # The berthd builds `berth upgrade` puts on Mac boxes; the Linux ones
    # come in berth's own archive.
    resource "berthd-darwin-arm64" do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.9/berthd-darwin-arm64.tar.gz"
      sha256 "0083201db702bf320fc11a203f8e3c2ba86a7c19114c000f1ea2f8ea5d6c0908"
    end
    resource "berthd-darwin-amd64" do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.9/berthd-darwin-amd64.tar.gz"
      sha256 "3f569251cf99c44d769353497f0cc9e3b42b94dd5735566ece6e2d9c06cf2117"
    end
  end
  on_linux do
    on_arm do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.9/berth-linux-arm64.tar.gz"
      sha256 "967a5d1265befc9963705b414ad414644ba25c2b6b4b7f7bf38d4c103faf09b6"
    end
    on_intel do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.9/berth-linux-amd64.tar.gz"
      sha256 "629931d12a4cb7711c103fd098121b878915d143caf55a1ac193b0b6c54b6b21"
    end
  end

  def install
    # berth looks beside its own file (through the link in bin) for the
    # berthd and tmux builds it uploads to boxes.
    libexec.install Dir["*"]
    if OS.mac?
      %w[arm64 amd64].each do |arch|
        resource("berthd-darwin-#{arch}").stage { libexec.install "berthd" => "berthd-darwin-#{arch}" }
      end
    end
    bin.install_symlink libexec/"berth"
  end

  def caveats
    <<~EOS
      Start the laptop agent, and have it start when you log in:
        berth agent install
      Add a box: berth add ssh USER@HOST (see berth help).
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/berth version")
  end
end
